"""Regenerate both complete PD metric definitions and Go oracle test inputs.

Usage: python3 scripts/generate_pd_metrics.py <pinned-pd-module-directory>
The input hashes are intentionally pinned; reviewing a source upgrade requires
updating the package inventory and the oracle, not silently accepting new syntax.
"""
import hashlib
import json
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = Path(sys.argv[1])
PIN = 'v0.0.0-20260805103528-afa43111d149'
PACKAGES = {'pd': 'metrics', 'resource_group': 'resource_group/controller/metrics'}
HASHES = {
'metrics': '9d966d40fbe46d4d5d925ed59d2a0291fa2f812f17a1029f48b535385ef8d34b',
'resource_group/controller/metrics': 'f45e77d16ca904ac6dd34eb5e91cdf7d966f57d6d6c0efe141441b2e6e7053dd',
}


def snake(s):
    return re.sub(r'([a-z0-9])([A-Z])', r'\1_\2', re.sub(r'([A-Z]+)([A-Z][a-z])', r'\1_\2', s)).lower()


def parse(package):
    package_root = SOURCE / package
    files = sorted(str(p.relative_to(package_root)) for p in package_root.rglob('*') if p.is_file())
    assert files == ['metrics.go'], (package, files)
    path = package_root / 'metrics.go'
    raw = path.read_bytes()
    assert hashlib.sha256(raw).hexdigest() == HASHES[package], path
    text = re.sub(r'//[^\n]*', '', raw.decode())
    constants = dict(re.findall(r'^\s*(\w+)\s*=\s*("[^"]*")', text, re.M))
    def value(s):
        return json.loads(constants.get(s.strip(), s.strip()))
    collectors = []
    for match in re.finditer(r'(\w+) = prometheus.New(\w+)\(\s*prometheus.\w+Opts\{(.*?)\}\s*,?\s*(?:\[\]string\{(.*?)\})?\)', text, re.S):
        name, kind, options, labels = match.groups()
        opts = dict(re.findall(r'(Namespace|Subsystem|Name|Help):\s*("[^"]*"|\w+)', options))
        bucket_match = re.search(r'Buckets:\s*prometheus.ExponentialBuckets\((.*?)\)', options)
        literal_match = re.search(r'Buckets:\s*\[\]float64\{(.*?)\}', options)
        buckets = None
        if bucket_match:
            start, factor, count = [float(x.strip()) for x in bucket_match[1].split(',')]
            buckets = [start * factor**i for i in range(int(count))]
        if literal_match:
            buckets = [float(x.strip()) for x in literal_match[1].split(',') if x.strip()]
        collectors.append(dict(source=name, field=snake(name), kind=kind,
            name='_'.join(value(opts[k]) for k in ['Namespace', 'Subsystem', 'Name']),
            help=value(opts['Help']), labels=[value(x) for x in (labels or '').split(',') if x.strip()], buckets=buckets))
    shortcuts = [dict(source=n, field=snake(n), collector=c, collector_field=snake(c), labels=[json.loads(x.strip()) for x in args.split(',')])
        for n,c,args in re.findall(r'(\w+) = (\w+)\.WithLabelValues\((.*?)\)', text)]
    declarations = re.findall(r'^\s*(\w+)\s+\*?prometheus\.(HistogramVec|Histogram|CounterVec|GaugeVec|Observer)\s*$', text, re.M)
    assert {x for x,_ in declarations} == {x['source'] for x in collectors+shortcuts}, ({x for x,_ in declarations} ^ {x['source'] for x in collectors+shortcuts})
    registered = re.findall(r'prometheus.MustRegister\((\w+)\)', text)
    assert set(registered) <= {x['source'] for x in collectors}
    return dict(package=package, collectors=collectors, shortcuts=shortcuts, registered=registered,
                constants={k:json.loads(v) for k,v in constants.items()})


def definitions(data):
    out = ['// Copyright 2026 TiKV Project Authors. Licensed under Apache-2.0.',
        '// Generated by scripts/generate_pd_metrics.py from pinned PD source. DO NOT EDIT.',
        'use std::collections::HashMap;',
        'use prometheus::{Histogram, HistogramOpts, HistogramVec, CounterVec, GaugeVec, Opts, Registry};',
        'use prometheus::core::Collector;',
        '#[derive(Clone)]', 'pub struct Metrics {']
    for item in data['collectors']+data['shortcuts']:
        out += [f"    /// Go `{item['source']}`.", f"    pub {item['field']}: {item.get('kind', 'Histogram')},"]
    out += ['}', 'impl Metrics {', '    pub fn new(labels: HashMap<String, String>) -> prometheus::Result<Self> {']
    for x in data['collectors']:
        name,help_text,kind = json.dumps(x['name']),json.dumps(x['help']),x['kind']
        options = f'Opts::new({name}, {help_text}).const_labels(labels.clone())'
        if kind.startswith('Histogram'):
            options = f'HistogramOpts::new({name}, {help_text}).const_labels(labels.clone()).buckets(vec!{json.dumps(x["buckets"])})'
        args = ', &'+json.dumps(x['labels']) if kind.endswith('Vec') else ''
        method = 'new' if kind.endswith('Vec') else 'with_opts'
        out += [f"        let {x['field']} = {kind}::{method}({options}{args})?;"]
    for x in data['shortcuts']:
        out += [f"        let {x['field']} = {x['collector_field']}.with_label_values(&{json.dumps(x['labels'])});"]
    out += ['        Ok(Self {'] + [f"            {x['field']}," for x in data['collectors']+data['shortcuts']] + ['        })', '    }',
        '    /// Register only collectors listed by the pinned Go package.',
        '    pub fn register_metrics(&self, registry: &Registry) -> prometheus::Result<()> {']
    out += [f'        registry.register(Box::new(self.{snake(x)}.clone()))?;' for x in data['registered']]
    out += ['        Ok(())', '    }', '    #[cfg(test)]', '    pub(super) fn all_collectors(&self) -> Vec<(&str, Box<dyn Collector>)> {', '        vec![']
    out += [f'            ("{x["source"]}", Box::new(self.{x["field"]}.clone())),' for x in data['collectors']]
    out += ['        ]', '    }', '    #[cfg(test)]', '    pub(super) fn exercise_oracle(&self) {']
    for x in data['collectors']:
        expr=f'self.{x["field"]}'
        if x['kind'].endswith('Vec'):
            expr += '.with_label_values(&'+json.dumps(['variable'+str(i) for i in range(len(x['labels']))])+')'
        method = 'observe(1.25)' if x['kind'].startswith('Histogram') else ('inc_by(1.25)' if x['kind'].startswith('Counter') else 'set(1.25)')
        out += [f'        {expr}.{method};']
    out += [f'        self.{x["field"]}.observe({float(i+2)});' for i,x in enumerate(data['shortcuts'])]
    out += ['    }', '}']
    # Imports vary between packages; never suppress actual unused fields/types.
    joined='\n'.join(out)+'\n'
    if not data['shortcuts'] and not any(x['kind']=='Histogram' for x in data['collectors']):
        joined=joined.replace('Histogram, ', '')
    return joined.replace('use prometheus::core::Collector;', '#[cfg(test)]\nuse prometheus::core::Collector;')


def oracle(data):
    out=['// Generated test input; copy into the exact upstream package, then run go test.',
         'package metrics', 'import ("encoding/json"; "os"; "testing"; "github.com/prometheus/client_golang/prometheus")',
         'func TestRustParityCollectorOracle(t *testing.T) {',
         'initMetrics(prometheus.Labels{"cluster": "oracle"})']
    if data['package']=='metrics':out+=['initLabelValues()']
    for x in data['collectors']:
        expr=x['source']
        if x['kind'].endswith('Vec'):expr+='.WithLabelValues('+','.join(json.dumps('variable'+str(i)) for i in range(len(x['labels'])))+')'
        method='Observe(1.25)' if x['kind'].startswith('Histogram') else ('Add(1.25)' if x['kind'].startswith('Counter') else 'Set(1.25)')
        out+=[expr+'.'+method]
    out += [f'{x["source"]}.Observe({i+2})' for i,x in enumerate(data['shortcuts'])]
    out+=['collectors := map[string]prometheus.Collector{']+[f'"{x["source"]}": {x["source"]},' for x in data['collectors']]+['}',
        'snapshots := map[string]interface{}{}',
        'for name, collector := range collectors {',
        'registry := prometheus.NewRegistry(); registry.MustRegister(collector)',
        'families, err := registry.Gather(); if err != nil { t.Fatal(err) }',
        'if len(families)!=1 { t.Fatalf("%s: families %d", name, len(families)) }',
        'snapshots[name] = families[0]', '}',
        'payload, err := json.Marshal(snapshots); if err != nil { t.Fatal(err) }',
        'var normalized interface{}; if err := json.Unmarshal(payload, &normalized); err != nil { t.Fatal(err) }; stripCreationTimes(normalized)',
        'payload, err = json.MarshalIndent(normalized, "", "  "); if err != nil { t.Fatal(err) }',
        'if err := os.WriteFile(os.Getenv("PD_METRICS_ORACLE")+"/'+('pd' if data['package']=='metrics' else 'resource_group')+'.json", payload, 0600); err != nil { t.Fatal(err) }', '}']
    out += ['func stripCreationTimes(v interface{}) { switch x := v.(type) { case map[string]interface{}: delete(x, "created_timestamp"); for _, child := range x { stripCreationTimes(child) }; case []interface{}: for _, child := range x { stripCreationTimes(child) } } }']
    return '\n'.join(out)+'\n'

for name, package in PACKAGES.items():
    data=parse(package)
    directory=ROOT/'src/pd/metrics'
    directory.mkdir(parents=True, exist_ok=True)
    target=directory/(name+'_definitions.rs')
    target.write_text(definitions(data))
    subprocess.run(['rustfmt','--edition','2021',str(target)], check=True)
    fixture=ROOT/'doc/pd-metrics-oracle'
    fixture.mkdir(parents=True, exist_ok=True)
    oracle_path = fixture / (name + '_test.go.txt')
    oracle_path.write_text(oracle(data))
    subprocess.run(['gofmt', '-s', '-w', str(oracle_path)], check=True)
    (fixture/(name+'_declarations.json')).write_text(json.dumps(data,indent=2)+'\n')
    print(name, len(data['collectors']), 'collectors,', len(data['shortcuts']), 'observers')
